//Approach 2: Using binary search. TC: O(nlogn) SC: O(1)
//Editorial: https://leetcode.com/problems/special-array-with-x-elements-greater-than-or-equal-x/discuss/1295326/C%2B%2B-Solution-Using-Binary-Search-O(n*log1000)-Time-and-O(1)-Space
class Solution {
public:
    int solve(vector<int> &nums,int mid)
    {
        int cnt=0;
        for(auto it:nums)
        {
            if(it>=mid)
                cnt+=1;
        }
        return cnt;
    }
    int specialArray(vector<int>& nums) {
        int n=nums.size();
        int low=0,high=n;
        while(low<=high)
        {
            int mid=low+(high-low)/2;
            int ans=solve(nums,mid);
            if(ans==mid)
                return mid;
            else if(ans<mid)
                high=mid-1;
            else
                low=mid+1;
        }
        return -1;
    }
};

class Solution(object):
    def specialArray(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        n = len(nums)
        cnt = [0] * (n + 1)
        for num in nums:
            cnt[min(num, n)] += 1
        for i in range(len(cnt) - 1, -1, -1):
            if i != len(cnt) - 1:
                cnt[i] += cnt[i + 1]
            if cnt[i] == i:
                return i
        return -1
